from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], workers: int = 4) -> int:
    """Sum of square(x) for every x in xs, with the squares computed in
    parallel on a thread pool of `workers` threads.

    The result is identical for every worker count. An empty list gives 0.
    Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return sum(pool.map(square, xs))


def test_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_empty() -> None:
    assert sum_squares([]) == 0


def test_single() -> None:
    assert sum_squares([7]) == 49


def test_negatives_and_zero() -> None:
    assert sum_squares([-3, 0, 3]) == 18


def test_large_values_exact() -> None:
    big = 10**30
    assert sum_squares([big, -big]) == 2 * big * big


@pytest.mark.parametrize("workers", [1, 2, 3, 4, 8, 64])
def test_same_result_at_every_worker_count(workers: int) -> None:
    xs = list(range(-500, 500))
    expected = sum(x * x for x in xs)
    assert sum_squares(xs, workers=workers) == expected


@pytest.mark.parametrize("workers", [1, 2, 5, 100])
def test_more_workers_than_items(workers: int) -> None:
    assert sum_squares([2, 3], workers=workers) == 13
    assert sum_squares([], workers=workers) == 0


def test_default_matches_explicit_workers() -> None:
    xs = [5, -4, 3, 2, 1]
    assert sum_squares(xs) == sum_squares(xs, workers=1)


def test_order_independent() -> None:
    xs = [4, -1, 9, 0, 2]
    assert sum_squares(xs, workers=3) == sum_squares(xs[::-1], workers=3)


def test_input_not_mutated() -> None:
    xs = [3, 1, 2]
    sum_squares(xs, workers=2)
    assert xs == [3, 1, 2]


@pytest.mark.parametrize("workers", [0, -1])
def test_invalid_workers(workers: int) -> None:
    with pytest.raises(ValueError):
        sum_squares([1, 2], workers=workers)

